import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def euler_phi(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def order_of_3_mod_k(k):
    if k == 1:
        return 1 # Should not happen for k>1 in the sum, but safety check

    # We need to find the smallest k >= 1 such that 3^k = 1 (mod k)
    # Since we are dealing with k that divide m, we assume gcd(3, k) = 1 unless k=1.
    # If gcd(3, k) > 1, the order is undefined in the group of units.
    # However, for the cycle structure analysis, the length of the cycle is defined by 3^k = 1 (mod m'),
    # where m' = k. If gcd(3, k) > 1, then 3^k will never be 1 (mod k).
    # Since 3 is prime, this only happens if k is a multiple of 3.
    # The problem states m is not divisible by 3.
    # If k | m and m is not divisible by 3, then k is not divisible by 3.
    # Thus gcd(3, k) = 1 is guaranteed for k|m.

    k_val = k
    order = 1
    # Check powers of 3 until it reaches 1 mod k
    while True:
        if pow(3, order, k_val) == 1:
            return order
        order += 1

def calculate_cycles(m):
    if m <= 1:
        return 0

    divisors = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.append(i)
            if i * i != m:
                divisors.append(m // i)

    total_cycles = 0

    # Sum over k|m, k>1
    for k in divisors:
        if k > 1:
            # Calculate contribution from cycles associated with m' = k
            phi_k = euler_phi(k)
            ord_k_3 = order_of_3_mod_k(k)

            # The contribution is phi(k) / ord_k(3). Since ord_k(3) divides phi(k), this is an integer.
            contribution = phi_k // ord_k_3
            total_cycles += contribution

    return total_cycles

# Search for the second largest m < 200 such that 3 does not divide m and C(m) is odd.
m_candidates = []
for m in range(199, 1, -1):
    if m % 3 != 0:
        C_m = calculate_cycles(m)
        if C_m % 2 != 0:
            m_candidates.append(m)

# The list m_candidates is sorted descendingly.
if len(m_candidates) >= 2:
    second_largest_m = m_candidates[1]
    print(f"Found {len(m_candidates)} such values. The second largest is: {second_largest_m}")
else:
    print(f"Found only {len(m_candidates)} such values.")

import math

def get_order(a, n):
    """Computes the multiplicative order of a modulo n."""
    if math.gcd(a, n) != 1:
        raise ValueError("a and n must be coprime")

    phi = n - 1 # Since we only check prime m

    # Find all divisors of phi
    divisors = []
    for i in range(1, int(math.sqrt(phi)) + 1):
        if phi % i == 0:
            divisors.append(i)
            divisors.append(phi // i)

    divisors = sorted(list(set(d for d in divisors if d > 0)))

    # Check divisors in increasing order
    for d in divisors:
        if pow(a, d, n) == 1:
            return d
    return phi # Should not happen if phi is correct

def v2(n):
    """Returns the exponent of 2 in the prime factorization of n."""
    if n == 0:
        return float('inf')
    count = 0
    while n > 0 and n % 2 == 0:
        count += 1
        n //= 2
    return count

def is_prime(n):
    """Checks if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Iterate downwards from 199 to find the largest qualifying m < 200
solutions = []
for m in range(199, 1, -1):
    if m % 3 == 0:
        continue
    if not is_prime(m):
        continue

    # m is prime and m is not divisible by 3
    m_minus_1 = m - 1
    k = get_order(3, m)

    v2_m_minus_1 = v2(m_minus_1)
    v2_k = v2(k)

    if v2_m_minus_1 == v2_k:
        # C = (m-1)/k is odd
        solutions.append(m)

# The task asks for the second largest integer m
if len(solutions) >= 2:
    print(f"All solutions found: {solutions}")
    print(f"Largest solution: {solutions[0]}")
    print(f"Second largest solution: {solutions[1]}")
else:
    print(f"Found {len(solutions)} solution(s): {solutions}")

